		nextFeatureIdx := strings.Index(ci, "next roadmap work:")
		if shippedIdx < 0 || guardIdx < 0 || reparentIdx < 0 || nextFeatureIdx < 0 {
			t.Fatalf("docs/engineering-workflow.md is missing one of the required anchors (shipped=%d guard=%d reparent=%d next=%d)", shippedIdx, guardIdx, reparentIdx, nextFeatureIdx)
		}
		if shippedIdx >= guardIdx || guardIdx >= reparentIdx || reparentIdx >= nextFeatureIdx {
			t.Fatalf("docs/engineering-workflow.md must order: the shipped-slices heading (%d) before \"rebase plan guard\" (%d) before slice 13's \"safe reparent/restack\" (%d) before \"Next roadmap work:\" (%d)", shippedIdx, guardIdx, reparentIdx, nextFeatureIdx)
		}

		nextTail := ci[nextFeatureIdx : nextFeatureIdx+min(120, len(ci)-nextFeatureIdx)]
		if !strings.Contains(nextTail, "reparent completion context (#7)") ||
			!strings.Contains(nextTail, "path b implementation candidate") || !strings.Contains(nextTail, "unreleased") {
			t.Fatalf(`docs/engineering-workflow.md's "Next roadmap work:" sentence must name reparent completion context (#7) as an unreleased Path B implementation candidate, got: %q`, nextTail)
		}
		if !strings.Contains(content, "fix-reparent-completion-context") {
			t.Fatal("docs/engineering-workflow.md must name the separate issue-seven feature boundary")
		}
		if !strings.Contains(normalizeProse(content), "ordinary sync safety (#4) is fully released and verified in v1.2.18-rc.2") {
			t.Fatal("docs/engineering-workflow.md must retain the verified ordinary-sync release milestone before advancing the target")
		}
		if !strings.Contains(normalizeProse(content), "slash-containing worktree injection (#1) is fully released and verified in v1.2.18-rc.3") {
			t.Fatal("docs/engineering-workflow.md must retain the verified injection release milestone before advancing the target")
		}
		if !strings.Contains(normalizeProse(content), "scoped status projection (#3) is fully released and verified in v1.2.18-rc.4") {
			t.Fatal("docs/engineering-workflow.md must retain the verified scoped-status release milestone before advancing the target")
		}
		if !strings.Contains(normalizeProse(content), "role-aware templates (#2) are fully released and verified in v1.2.18-rc.5") {
			t.Fatal("docs/engineering-workflow.md must retain the verified role-aware template release milestone before advancing the target")
		}
		if !strings.Contains(normalizeProse(content), "template conflict resolution is fully released and verified in v1.2.18-rc.6") {
			t.Fatal("docs/engineering-workflow.md must retain the verified conflict-resolution release milestone before advancing the target")
		}
		if !strings.Contains(normalizeProse(content), "external feature rename (#5) is fully released and verified in v1.2.18-rc.7") {
			t.Fatal("docs/engineering-workflow.md must retain the verified rename release milestone before advancing the target")
		}
		if !strings.Contains(normalizeProse(content), "scoped standalone push (#6) is fully released and verified in v1.2.18-rc.8") {
